import {buildChatIndex,answerArtifactQuestion,searchNasaLibrary} from './chat-knowledge.js';

const allowedSource=url=>{try{const value=new URL(url);return value.protocol==='https:'&&(value.hostname==='nasa.gov'||value.hostname.endsWith('.nasa.gov')||['www.uahirise.org','an.rsl.wustl.edu'].includes(value.hostname));}catch{return false;}};
export function createArtifactChat({icon,esc,getContext=()=>null}){
 const host=document.createElement('aside');host.id='echo-chat';host.setAttribute('aria-label','NASA artifact chat');document.body.append(host);
 const launcher=document.createElement('button');launcher.className='echo-chat-launcher';launcher.setAttribute('aria-label','Ask Echo about NASA artifacts');launcher.setAttribute('aria-expanded','false');launcher.innerHTML=`${icon('spark',21)}<span>Ask Echo</span>`;host.append(launcher);
 let open=false,dead=false,indexPromise=null,index=null,messages=[],context=null,lastScene=null,busy=false,request=0,controller=null,background=[];
 const cache=new Map();const $=selector=>host.querySelector(selector);
 const syncLauncher=()=>{if(dead)return;const destination=document.querySelector('.reading-story')||document.querySelector('.voyage')||document.querySelector('.expedition-gate')||document.querySelector('.surface-expedition')||host;if(launcher.parentElement!==destination)destination.append(launcher);};
 const observer=new MutationObserver(syncLauncher);observer.observe(document.querySelector('#app'),{childList:true,subtree:true});syncLauncher();
 async function loadIndex(){if(!indexPromise)indexPromise=fetch('nasa-archive-records.json').then(response=>{if(!response.ok)throw new Error('Archive unavailable');return response.json();}).then(data=>{index=buildChatIndex(data);return index;}).catch(error=>{indexPromise=null;throw error;});return indexPromise;}
 function links(items){return (items||[]).filter(s=>allowedSource(s.url)).slice(0,4).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('book',13)} ${esc(s.title)} ${icon('arrow',12)}</a>`).join('');}
 function draw(){if(!open||dead)return;$('.echo-chat-log').innerHTML=messages.map((message,i)=>`<article class="echo-message echo-message-${message.role}">${message.role==='assistant'?'<span class="echo-message-name">ECHO / NASA RECORDS</span>':''}<p>${esc(message.text).replace(/\n\n/g,'</p><p>')}</p>${message.choices?.length?`<div class="echo-record-choices">${message.choices.map(choice=>`<button data-echo-record="${esc(choice.id)}">${esc(choice.label)} ${icon('right',14)}</button>`).join('')}</div>`:''}${message.sources?.length?`<div class="echo-source-links">${links(message.sources)}</div>`:''}${message.library?.length?`<div class="echo-library-results">${message.library.map(result=>`<a href="${esc(result.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(result.title)}</b><span>${esc(result.text)}</span>${icon('arrow',14)}</a>`).join('')}</div>`:''}${message.searchQuery?`<button class="echo-nasa-search" data-echo-search="${i}">${icon('globe',15)} Search NASA: ${esc(message.searchQuery)}</button>`:''}</article>`).join('');$('.echo-chat-log').setAttribute('aria-busy',String(busy));$('.echo-chat-status').textContent=busy?'Searching NASA records…':'';$('[data-echo-action="send"]').disabled=busy;$('.echo-chat-log').scrollTop=$('.echo-chat-log').scrollHeight;}
 function add(message){messages.push(message);if(messages.length>24)messages=messages.slice(-24);draw();}
 function show(){if(open||dead)return;open=true;launcher.hidden=true;launcher.setAttribute('aria-expanded','true');const scene=getContext();if(scene&&scene!==lastScene){context=scene;lastScene=scene;}
  document.dispatchEvent(new CustomEvent('echo-chat-open'));background=[document.querySelector('#app'),document.querySelector('#overlay')].filter(Boolean).map(el=>({el,inert:el.inert}));background.forEach(({el})=>el.inert=true);document.body.classList.add('echo-chat-open');
  host.insertAdjacentHTML('beforeend',`<section class="echo-chat-panel" role="dialog" aria-modal="true" aria-labelledby="echo-chat-title"><header class="echo-chat-header"><div class="echo-chat-avatar">${icon('spark',23)}</div><div><h2 id="echo-chat-title">Echo</h2><p>Abandoned artifact guide</p></div><button data-echo-action="clear" aria-label="Start a new conversation" title="Start a new conversation">${icon('reset',17)}</button><button data-echo-action="close" aria-label="Close artifact chat">${icon('close',20)}</button></header><div class="echo-chat-log" role="log" aria-live="polite" aria-relevant="additions text"></div><div class="echo-chat-bottom"><div class="echo-chat-starters"><button data-echo-prompt="Tell me about a recent abandoned artifact">A recent artifact</button><button data-echo-prompt="Tell me about Sojourner">Meet Sojourner</button><button data-echo-prompt="What did Apollo 15 leave?">Apollo 15 objects</button></div><form class="echo-chat-form"><label class="sr-only" for="echo-chat-question">Ask about a NASA artifact</label><input id="echo-chat-question" name="question" type="text" maxlength="400" autocomplete="off" required placeholder="Ask about an artifact…"><button data-echo-action="send" type="submit" aria-label="Send question">${icon('send',19)}</button></form><span class="echo-chat-status" role="status"></span><p class="echo-chat-note">Abandoned artifacts only · Source lookup, not generative AI. NASA search sends only the selected artifact’s name and mission. Historical records, not live status.</p></div></section>`);
  if(!messages.length)messages.push({role:'assistant',text:'Hi, I’m Echo. I only cover documented space hardware left behind, retired or lost on the Moon and Mars. Ask for a recent example or name an artifact. I’ll show its NASA sources and say when a record cannot answer.'});draw();$('#echo-chat-question').focus({preventScroll:true});loadIndex().catch(()=>{});
 }
 function close(){if(!open)return;open=false;++request;controller?.abort();controller=null;busy=false;$('.echo-chat-panel')?.remove();background.forEach(({el,inert})=>el.inert=inert);background=[];document.body.classList.remove('echo-chat-open');launcher.hidden=false;launcher.setAttribute('aria-expanded','false');syncLauncher();launcher.focus({preventScroll:true});document.dispatchEvent(new CustomEvent('echo-chat-close'));}
 async function ask(value,recordId=null){const question=String(value).trim().slice(0,400);if(!question||busy)return;const token=++request;add({role:'user',text:question});busy=true;draw();$('#echo-chat-question').value='';try{const loaded=await loadIndex();if(!open||dead||token!==request)return;const answer=answerArtifactQuestion({question,index:loaded,context,recordId});context=answer.context||context;add({role:'assistant',...answer});}catch{if(open&&token===request)add({role:'assistant',text:'The included archive could not load. Please try again when your connection is available. The stories remain available to explore.'});}finally{if(open&&token===request){busy=false;draw();$('#echo-chat-question').focus({preventScroll:true});}}}
 async function lookup(messageIndex){const message=messages[messageIndex],query=message?.searchQuery,recordId=message?.searchRecord;if(!query||!recordId||busy)return;const token=++request;add({role:'user',text:`Search NASA’s library for “${query}”.`});busy=true;draw();const activeController=new AbortController();controller=activeController;const timer=setTimeout(()=>activeController.abort(),10000);try{let results=cache.get(query);if(!results){results=await searchNasaLibrary(recordId,{index,signal:activeController.signal});cache.set(query,results);if(cache.size>20)cache.delete(cache.keys().next().value);}if(!open||dead||token!==request)return;add({role:'assistant',text:results.length?'Here are NASA library descriptions matched to this documented artifact and its mission. These short excerpts do not verify its present condition. Open a record for the full context.':'No NASA library descriptions passed the artifact-and-mission filter. I keep unrelated results out; you can still open the linked mission sources above.',library:results});}catch{if(open&&token===request)add({role:'assistant',text:'The wider NASA lookup is unavailable right now. You can still ask about the included mission records and lunar inventory.'});}finally{clearTimeout(timer);if(controller===activeController)controller=null;if(open&&token===request){busy=false;draw();$('#echo-chat-question').focus({preventScroll:true});}}}
 launcher.addEventListener('click',event=>{event.stopPropagation();show();});
 host.addEventListener('submit',event=>{if(event.target.matches('.echo-chat-form')){event.preventDefault();ask($('#echo-chat-question').value);}});
 host.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.echoAction==='close')close();if(button.dataset.echoAction==='clear'){++request;controller?.abort();busy=false;context=getContext()||null;messages=[{role:'assistant',text:'A fresh conversation about abandoned artifacts. Ask for a recent example, or name some hardware left on the Moon or Mars.'}];draw();$('#echo-chat-question').focus();}if(button.dataset.echoPrompt)ask(button.dataset.echoPrompt);if(button.dataset.echoRecord){const record=index?.records.find(r=>r.id===button.dataset.echoRecord);if(record)ask(`${record.name} · ${record.mission}`,record.id);}if(button.dataset.echoSearch!==undefined)lookup(Number(button.dataset.echoSearch));});
 host.addEventListener('keydown',event=>{if(!open)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();return;}if(event.key==='Tab'){event.stopPropagation();const items=[...$('.echo-chat-panel').querySelectorAll('button:not(:disabled),a,input')].filter(el=>el.getClientRects().length),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
 return {close,dispose(){close();dead=true;observer.disconnect();launcher.remove();host.remove();}};
}
